import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { UI_BUNDLE_SOURCES, UI_MODAL_SOURCES } from './lib/ui-source-catalog.mjs';

const scriptsDirectory = resolve(fileURLToPath(new URL('.', import.meta.url)));
const projectRoot = resolve(scriptsDirectory, '..');
const outputPath = resolve(projectRoot, 'assets/css/ui.bundle.css');
const modalOutputPath = resolve(projectRoot, 'assets/css/ui-modal.bundle.css');
const sources = UI_BUNDLE_SOURCES;
const modalSources = UI_MODAL_SOURCES;
const readStylesheet = relativePath => readFileSync(resolve(projectRoot, relativePath), 'utf8')
  .replace(/\r\n?/g, '\n')
  .trim();
const sourceContents = sources.map(relativePath => ({
  relativePath,
  content: readStylesheet(relativePath),
}));

const output = [
  '/* Generated by scripts/build-ui-bundle.mjs. Do not edit manually. */',
  `/* source-count: ${sources.length} */`,
  ...sourceContents.flatMap(({ relativePath, content }) => [
    `/* source: ${relativePath} */`,
    content,
  ]),
  '',
].join('\n\n');

writeFileSync(outputPath, output, 'utf8');
const modalOutput = [
  '/* Generated by scripts/build-ui-bundle.mjs. Do not edit manually. */',
  `/* modal-source-count: ${modalSources.length} */`,
  ...modalSources.flatMap(relativePath => [
    `/* modal-source: ${relativePath} */`,
    readStylesheet(relativePath),
  ]),
  '',
].join('\n\n');
writeFileSync(modalOutputPath, modalOutput, 'utf8');
console.log(`Generated UI bundle from ${sources.length} stylesheets and modal bundle from ${modalSources.length} stylesheet.`);
